exercises.solution:
using System;

public static class Grades
{
    public static string Grade(int score) => score switch
    {
        < 0 or > 100 => "invalid",
        >= 80 => "A",
        >= 65 => "B",
        >= 50 => "C",
        >= 40 => "D",
        _ => "E",
    };
}

